import{_ as r,C as e,o as t,c as m,a2 as i,b as a,w as h,a as g,E as u,a3 as o}from"./chunks/framework.2Es64uX1.js";const A=JSON.parse('{"title":"CHƯƠNG 1: TỔNG QUAN KỸ THUẬT PHẦN MỀM ỨNG DỤNG VÀ CÁC MÔ HÌNH PHÁT TRIỂN (SDLC)","description":"","frontmatter":{"source_file":"CHUONG_1_VIET_LAI.docx","source_type":"DOCX","parsed_by":"anydoc-v1.0","parsed_at":"2026-09-03T22:13:03.899594","original_size_bytes":36759},"headers":[],"relativePath":"ch01_tong_quan_sdlc.md","filePath":"ch01_tong_quan_sdlc.md"}'),l={name:"ch01_tong_quan_sdlc.md"};function p(d,n,s,v,y,b){const c=e("Mermaid");return t(),m("div",null,[n[4]||(n[4]=i('<h1 id="chuong-1-tong-quan-ky-thuat-phan-mem-ung-dung-va-cac-mo-hinh-phat-trien-sdlc" tabindex="-1">CHƯƠNG 1: TỔNG QUAN KỸ THUẬT PHẦN MỀM ỨNG DỤNG VÀ CÁC MÔ HÌNH PHÁT TRIỂN (SDLC) <a class="header-anchor" href="#chuong-1-tong-quan-ky-thuat-phan-mem-ung-dung-va-cac-mo-hinh-phat-trien-sdlc" aria-label="Permalink to &quot;CHƯƠNG 1: TỔNG QUAN KỸ THUẬT PHẦN MỀM ỨNG DỤNG VÀ CÁC MÔ HÌNH PHÁT TRIỂN (SDLC)&quot;">​</a></h1><p>Dự án Xuyên suốt: Giới thiệu Dr May Day v2.0 - Lựa chọn Mô hình Phát triển Phù hợp và Thiết lập Văn hóa Kỹ thuật Nền tảng cho Nền tảng Y tế Số</p><h2 id="_1-muc-tieu-hoc-tap-va-khung-nang-luc-thuc-chien" tabindex="-1">1. MỤC TIÊU HỌC TẬP VÀ KHUNG NĂNG LỰC THỰC CHIẾN <a class="header-anchor" href="#_1-muc-tieu-hoc-tap-va-khung-nang-luc-thuc-chien" aria-label="Permalink to &quot;1. MỤC TIÊU HỌC TẬP VÀ KHUNG NĂNG LỰC THỰC CHIẾN&quot;">​</a></h2><p>Sau khi hoàn thành chương này, người đọc có khả năng:</p><ul><li><p>Phân biệt &quot;Viết mã&quot; (Coding) và &quot;Kỹ thuật Phần mềm&quot; (Software Engineering); giải thích bản chất Hệ thống Xã hội-Kỹ thuật của phần mềm ứng dụng thực tế; giải thích cấu trúc chung của một SDLC và đặc trưng của các mô hình Thác nước, Chữ V, Tiến hóa/Xoắn ốc.</p></li><li><p>Áp dụng Ma trận Đánh giá để lựa chọn mô hình SDLC phù hợp cho một dự án cụ thể; áp dụng tư duy Agile/Lean và khung Scrum/Kanban cơ bản; tính toán và diễn giải 4 Chỉ số DORA cho một đội ngũ phát triển giả định.</p></li><li><p>Phân tích sự chuyển dịch văn hóa từ mô hình Silo truyền thống sang DevOps/DevSecOps; phân tích tác động của các công cụ AI-Augmented (GenAI, LLM) lên từng giai đoạn của SDLC.</p></li><li><p>Đánh giá và lựa chọn mô hình quy trình phát triển phù hợp nhất cho dự án Dr May Day v2.0 dựa trên đặc thù ngành y tế; đánh giá rủi ro bảo mật và hiện tượng ảo giác (hallucination) khi tích hợp trợ lý lập trình AI vào quy trình phát triển.</p></li></ul><h2 id="_2-noi-dung-ly-thuyet-cot-loi-core-concepts" tabindex="-1">2. NỘI DUNG LÝ THUYẾT CỐT LÕI (CORE CONCEPTS) <a class="header-anchor" href="#_2-noi-dung-ly-thuyet-cot-loi-core-concepts" aria-label="Permalink to &quot;2. NỘI DUNG LÝ THUYẾT CỐT LÕI (CORE CONCEPTS)&quot;">​</a></h2><h3 id="_1-1-khai-niem-va-tu-duy-ky-thuat-phan-mem-ung-dung" tabindex="-1">1.1. Khái niệm và Tư duy Kỹ thuật Phần mềm Ứng dụng <a class="header-anchor" href="#_1-1-khai-niem-va-tu-duy-ky-thuat-phan-mem-ung-dung" aria-label="Permalink to &quot;1.1. Khái niệm và Tư duy Kỹ thuật Phần mềm Ứng dụng&quot;">​</a></h3><p>Trước khi đi sâu vào các mô hình quy trình cụ thể, chương này khởi đầu bằng câu hỏi nền tảng nhất: Kỹ thuật Phần mềm khác gì với việc đơn thuần viết mã? Câu trả lời cho câu hỏi tưởng chừng đơn giản này định hình toàn bộ cách tiếp cận của cuốn sách xuyên suốt các chương còn lại — từ Kỹ thuật Yêu cầu (Chương 2), Thiết kế Hướng đối tượng (Chương 3), cho đến Kiến trúc Hệ thống (Chương 6).</p><h4 id="_1-1-1-phan-biet-viet-ma-va-ky-thuat-phan-mem" tabindex="-1">1.1.1. Phân biệt &quot;Viết mã&quot; và &quot;Kỹ thuật Phần mềm&quot; <a class="header-anchor" href="#_1-1-1-phan-biet-viet-ma-va-ky-thuat-phan-mem" aria-label="Permalink to &quot;1.1.1. Phân biệt &quot;Viết mã&quot; và &quot;Kỹ thuật Phần mềm&quot;&quot;">​</a></h4><p>Viết mã (Coding) là hoạt động chuyển đổi một thuật toán hoặc logic đã được xác định rõ ràng thành mã nguồn thực thi được bằng một ngôn ngữ lập trình cụ thể — một kỹ năng cá nhân, tập trung vào cú pháp và logic cục bộ. Kỹ thuật Phần mềm (Software Engineering), theo định nghĩa chính thức của IEEE Std 610.12, là &quot;việc áp dụng một cách tiếp cận có hệ thống, có kỷ luật, có thể định lượng được vào việc phát triển, vận hành và bảo trì phần mềm&quot; — một hoạt động kỹ thuật ở quy mô tổ chức, không chỉ dừng ở việc viết ra mã nguồn chạy đúng.</p><table tabindex="0"><thead><tr><th>Tiêu chí</th><th>Viết mã (Coding)</th><th>Kỹ thuật Phần mềm (Software Engineering)</th></tr></thead><tbody><tr><td>Phạm vi quan tâm</td><td>Một hàm, một module, logic cục bộ</td><td>Toàn bộ vòng đời: yêu cầu, thiết kế, kiểm thử, vận hành, bảo trì</td></tr><tr><td>Đơn vị làm việc</td><td>Cá nhân</td><td>Đội ngũ, tổ chức, nhiều bên liên quan</td></tr><tr><td>Tiêu chí thành công</td><td>Chương trình chạy đúng với dữ liệu đầu vào đã thử</td><td>Đúng, dễ bảo trì, có thể mở rộng, đúng tiến độ, đúng ngân sách</td></tr><tr><td>Thời gian sống của sản phẩm</td><td>Thường ngắn hạn, ít quan tâm bảo trì lâu dài</td><td>Nhiều năm, thậm chí hàng chục năm vận hành thực tế</td></tr><tr><td>Ví dụ trong Dr May Day v2.0</td><td>Viết hàm tính điểm UAS7 chạy đúng cho một ca thử nghiệm</td><td>Đảm bảo hàm đó được kiểm thử, tài liệu hóa, chịu tải hàng nghìn bệnh nhân, và có thể sửa an toàn sau 2 năm vận hành</td></tr></tbody></table><p>Sự khác biệt này không chỉ mang tính học thuật — nó giải thích trực tiếp vì sao một bạn có thể viết được một chương trình tính điểm UAS7 chạy đúng trong vài giờ, nhưng một hệ thống Dr May Day v2.0 thực thụ, phục vụ hàng chục bệnh viện với yêu cầu về độ tin cậy, bảo mật dữ liệu y tế và khả năng mở rộng, đòi hỏi hàng tháng công sức của cả một đội ngũ đa ngành. Toàn bộ cuốn sách này, từ Kỹ thuật Yêu cầu đến Kiến trúc Hệ thống và DevSecOps, chính là nội dung của &quot;Kỹ thuật&quot; trong Kỹ thuật Phần mềm — những gì vượt ra ngoài phạm vi thuần túy của việc viết mã.</p><h4 id="_1-1-2-thach-thuc-cot-loi-cua-phan-mem-ung-dung-thuc-te" tabindex="-1">1.1.2. Thách thức Cốt lõi của Phần mềm Ứng dụng Thực tế <a class="header-anchor" href="#_1-1-2-thach-thuc-cot-loi-cua-phan-mem-ung-dung-thuc-te" aria-label="Permalink to &quot;1.1.2. Thách thức Cốt lõi của Phần mềm Ứng dụng Thực tế&quot;">​</a></h4><p>Fred Brooks, trong bài luận kinh điển &quot;No Silver Bullet — Essence and Accidents of Software Engineering&quot; (1987), lập luận rằng phần mềm vốn dĩ khó xây dựng không phải chỉ vì các khó khăn kỹ thuật ngẫu nhiên (Accidents — như công cụ kém, ngôn ngữ lập trình hạn chế, có thể giải quyết bằng công nghệ tốt hơn), mà còn vì bốn thuộc tính cố hữu (Essence) không thể loại bỏ hoàn toàn dù công nghệ có tiến bộ đến đâu:</p><p>Độ phức tạp (Complexity): Phần mềm doanh nghiệp thực tế chứa vô số trạng thái, quy tắc nghiệp vụ và trường hợp ngoại lệ tương tác lẫn nhau — độ phức tạp này tăng phi tuyến theo quy mô hệ thống, không giống các cấu trúc vật lý có thể lặp lại các thành phần giống hệt nhau (như các viên gạch giống nhau trong một tòa nhà).</p><p>Tính tuân thủ (Conformity): Phần mềm phải tuân theo vô số ràng buộc do con người và tổ chức khác áp đặt — quy định y tế, giao diện hệ thống cũ (legacy), thói quen làm việc của bác sĩ — những ràng buộc này không có logic nội tại nhất quán vì chúng phản ánh sự tùy tiện của lịch sử tổ chức, không phải do kỹ sư phần mềm tự do thiết kế.</p><p>Khả năng thay đổi (Changeability): Phần mềm chịu áp lực thay đổi liên tục hơn hầu hết mọi sản phẩm kỹ thuật khác, vì nó dễ thay đổi hơn phần cứng — ngay khi Dr May Day v2.0 vừa hoàn thành, Bộ Y tế đã có thể ban hành hướng dẫn mới yêu cầu điều chỉnh thang điểm UAS7 (như đã minh họa ở Case Study Chương 2).</p><p>Tính vô hình (Invisibility): Không giống một tòa nhà hay cây cầu có thể quan sát trực tiếp bằng mắt thường, cấu trúc phần mềm không có hình dạng vật lý tự nhiên — buộc phải trừu tượng hóa thành các mô hình (UML, DFD, C4 — sẽ học ở Chương 2 và 3) để có thể trao đổi và tư duy về nó.</p><p>Ward Cunningham, người khởi xướng khái niệm Nợ Kỹ thuật (Technical Debt) năm 1992, dùng phép ẩn dụ tài chính để mô tả hệu quả của việc chấp nhận các giải pháp nhanh nhưng chưa hoàn thiện để kịp tiến độ: giống như một khoản vay, nợ kỹ thuật cần được &quot;trả lãi&quot; liên tục dưới dạng chi phí bảo trì tăng cao, và nếu không được &quot;trả gốc&quot; (tái cấu trúc, đã học ở Chương 3) kịp thời, lãi suất sẽ tích lũy đến mức làm tê liệt khả năng phát triển tính năng mới của đội ngũ.</p><p>Một hệ quả thực tiễn ít được chú ý của bốn thuộc tính cố hữu này là Định luật Hyrum (Hyrum&#39;s Law), do kỹ sư Hyrum Wright tại Google phát biểu: &quot;Với một API đủ nhiều người dùng, không quan trọng bạn cam kết gì trong hợp đồng API — mọi hành vi quan sát được của hệ thống của bạn sẽ bị ai đó phụ thuộc vào.&quot; Nói cách khác, dù đội ngũ Dr May Day v2.0 chỉ chính thức công bố (document) một phần hành vi của API UAS7Score, một khi hệ thống có đủ nhiều dịch vụ khách hàng (client) sử dụng, ngay cả các chi tiết hiện thực không chủ đích (như thứ tự trả về của một danh sách, hay độ trễ phản hồi cụ thể) cũng có thể bị các client khác âm thầm phụ thuộc vào — khiến việc thay đổi &quot;chi tiết hiện thực nội bộ tưởng chừng vô hại&quot; trở nên rủi ro hơn nhiều so với dự đoán ban đầu. Đây chính là biểu hiện cụ thể của thuộc tính Độ phức tạp (Complexity) khi hệ thống đạt đến quy mô đủ lớn.</p><h4 id="_1-1-3-he-thong-xa-hoi-va-ky-thuat" tabindex="-1">1.1.3. Hệ thống Xã hội và Kỹ thuật <a class="header-anchor" href="#_1-1-3-he-thong-xa-hoi-va-ky-thuat" aria-label="Permalink to &quot;1.1.3. Hệ thống Xã hội và Kỹ thuật&quot;">​</a></h4><p>Phần mềm ứng dụng thực tế không tồn tại độc lập như một hiện vật thuần túy kỹ thuật — nó luôn được nhúng vào trong một Hệ thống Xã hội-Kỹ thuật (Socio-Technical System), bao gồm cả thành phần công nghệ (mã nguồn, cơ sở dữ liệu, hạ tầng) lẫn thành phần con người và tổ chức (quy trình làm việc của bác sĩ, chính sách bệnh viện, thói quen của bệnh nhân). Một hệ thống được thiết kế hoàn hảo về mặt kỹ thuật vẫn có thể thất bại hoàn toàn nếu không phù hợp với thực tế vận hành của tổ chức sử dụng nó.</p><p>Ví dụ minh họa trong Dr May Day v2.0: phiên bản thử nghiệm đầu tiên yêu cầu bác sĩ nhập đầy đủ 10 trường thông tin cho mỗi lượt khám — về mặt kỹ thuật, hệ thống hoạt động hoàn hảo, không có lỗi phần mềm nào. Nhưng trên thực tế, bác sĩ tại các phòng khám đông bệnh nhân không có đủ thời gian nhập liệu đầy đủ giữa các ca khám liên tục, dẫn đến tỷ lệ bỏ sót dữ liệu cao — không phải vì lỗi kỹ thuật, mà vì thiết kế chưa tính đến ràng buộc thời gian thực tế của quy trình khám bệnh. Bài học này định hình toàn bộ triết lý Kỹ thuật Yêu cầu ở Chương 2: khảo sát yêu cầu không chỉ hỏi &quot;hệ thống cần làm gì&quot; mà còn phải quan sát &quot;quy trình làm việc thực tế diễn ra như thế nào&quot;.</p><p>Nhìn rộng hơn, mọi hệ thống phần mềm ứng dụng đều tồn tại trong một mạng lưới ba lớp tương tác lẫn nhau: lớp Kỹ thuật (mã nguồn, hạ tầng — chủ đề của Chương 3, 6), lớp Quy trình (cách công việc được tổ chức — chủ đề của mục 1.2-1.4), và lớp Con người/Tổ chức (thói quen, động lực, cấu trúc quyền lực của tổ chức sử dụng phần mềm). Một dự án thất bại hiếm khi chỉ vì một lớp — thường là do sự mất cân bằng hoặc xung đột giữa ba lớp này, một chủ đề mà kỹ sư phần mềm giỏi cần có khả năng nhận diện sớm, không chỉ giới hạn tư duy trong phạm vi lớp Kỹ thuật quen thuộc nhất với mình.</p><h3 id="_1-2-dong-đoi-phat-trien-phan-mem-va-cac-mo-hinh-quy-trinh-co-đien" tabindex="-1">1.2. Dòng đời Phát triển Phần mềm và Các Mô hình Quy trình Cổ điển <a class="header-anchor" href="#_1-2-dong-đoi-phat-trien-phan-mem-va-cac-mo-hinh-quy-trinh-co-đien" aria-label="Permalink to &quot;1.2. Dòng đời Phát triển Phần mềm và Các Mô hình Quy trình Cổ điển&quot;">​</a></h3><p>Vòng đời Phát triển Phần mềm (Software Development Life Cycle - SDLC) là một khuôn khổ mô tả các giai đoạn cần thiết để xây dựng phần mềm chất lượng cao, từ ý tưởng ban đầu đến khi ngừng vận hành. Mục này trình bày cấu trúc chung của mọi SDLC, sau đó đi qua ba mô hình quy trình cổ điển từng thống trị ngành công nghiệp phần mềm trước khi Agile ra đời (trình bày ở mục 1.3), và khép lại bằng công cụ giúp lựa chọn mô hình phù hợp cho từng bối cảnh dự án cụ thể. Việc nắm vững các mô hình &quot;cổ điển&quot; này, dù Agile đã trở thành xu hướng chủ đạo, vẫn cần thiết vì nhiều tổ chức — đặc biệt trong lĩnh vực y tế, hàng không, tài chính với yêu cầu tuân thủ nghiêm ngặt — vẫn áp dụng các mô hình này cho một phần hoặc toàn bộ dự án, và tư duy quản trị rủi ro của chúng vẫn có giá trị tham chiếu quan trọng ngay cả trong bối cảnh Agile.</p><h4 id="_1-2-1-cau-truc-mot-sdlc-tieu-chuan" tabindex="-1">1.2.1. Cấu trúc một SDLC Tiêu chuẩn <a class="header-anchor" href="#_1-2-1-cau-truc-mot-sdlc-tieu-chuan" aria-label="Permalink to &quot;1.2.1. Cấu trúc một SDLC Tiêu chuẩn&quot;">​</a></h4>',27)),(t(),a(o,null,{default:h(()=>[u(c,{id:"mermaid-169",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20subgraph%20Waterfall%5B%22M%C3%B4%20h%C3%ACnh%20Th%C3%A1c%20n%C6%B0%E1%BB%9Bc%20(Sequential%20Waterfall)%22%5D%0A%20%20%20%20%20%20%20%20W1%5B%221.%20Y%C3%AAu%20c%E1%BA%A7u%20(Requirements)%22%5D%20--%3E%20W2%5B%222.%20Thi%E1%BA%BFt%20k%E1%BA%BF%20(Architecture%2FDesign)%22%5D%0A%20%20%20%20%20%20%20%20W2%20--%3E%20W3%5B%223.%20C%C3%A0i%20%C4%91%E1%BA%B7t%20(Implementation)%22%5D%0A%20%20%20%20%20%20%20%20W3%20--%3E%20W4%5B%224.%20Ki%E1%BB%83m%20th%E1%BB%AD%20(Verification%2FTesting)%22%5D%0A%20%20%20%20%20%20%20%20W4%20--%3E%20W5%5B%225.%20Tri%E1%BB%83n%20khai%20%26%20B%E1%BA%A3o%20tr%C3%AC%20(Maintenance)%22%5D%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20Agile%5B%22M%C3%B4%20h%C3%ACnh%20Agile%20(L%E1%BA%B7p%20%26%20T%C4%83ng%20d%E1%BA%A7n%20-%20Iterative%20%26%20Incremental)%22%5D%0A%20%20%20%20%20%20%20%20direction%20LR%0A%20%20%20%20%20%20%20%20A1%5B%22Sprint%20Planning%22%5D%20--%3E%20A2%5B%22Ph%C3%A1t%20tri%E1%BB%83n%20%26%20Test%22%5D%0A%20%20%20%20%20%20%20%20A2%20--%3E%20A3%5B%22B%E1%BA%A3n%20giao%20Increment%22%5D%0A%20%20%20%20%20%20%20%20A3%20--%3E%20A4%5B%22Review%20%26%20Retro%22%5D%0A%20%20%20%20%20%20%20%20A4%20--%3E%7C%22Sprint%20ti%E1%BA%BFp%20theo%22%7C%20A1%0A%20%20%20%20end%0A%20%20%20%20style%20Waterfall%20fill%3A%23f5f5f5%2Cstroke%3A%239e9e9e%0A%20%20%20%20style%20Agile%20fill%3A%23e8f5e9%2Cstroke%3A%232e7d32%2Cstroke-width%3A2px%0A"})]),fallback:h(()=>[...n[0]||(n[0]=[g(" Loading... ",-1)])]),_:1})),n[5]||(n[5]=i(`<p><em>Hình 1.1: So sánh bản chất dòng chảy quy trình giữa Thác nước truyền thống và Vòng lặp Agile.</em></p><p>Dù các mô hình quy trình cụ thể khác nhau về trình tự và mức độ lặp lại, hầu hết đều chia sẻ chung năm hoạt động khung tổng quát (Generic Framework Activities) sau, theo cách hệ thống hóa phổ biến của Roger Pressman:</p><p><code> ext ┌──────────────┐ ┌───────────┐ ┌───────────┐ ┌───────────────┐ ┌────────────┐ │ Giao tiếp │─►│ Lập kế │─►│ Mô hình │─►│ Xây dựng │─►│ Triển khai │ │(Communication)│ │hoạch(Plan) │ │(Modeling) │ │(Construction) │ │(Deployment) │ └──────────────┘ └───────────┘ └───────────┘ └───────────────┘ └────────────┘ Khảo sát yêu Ước lượng, Phân tích &amp; Viết mã + Bàn giao, cầu ban đầu lập lịch thiết kế Kiểm thử phản hồi, bảo trì </code></p><p>Hình 1.1 — Năm Hoạt động Khung Tổng quát của một SDLC (theo Pressman)</p><p>Năm hoạt động này không nhất thiết phải thực hiện tuần tự một lần duy nhất — sự khác biệt cốt lõi giữa các mô hình quy trình trình bày ở các mục tiếp theo chính là cách chúng sắp xếp, lặp lại, hoặc chồng lấp năm hoạt động này theo thời gian. Bảng dưới đây minh họa cụ thể năm hoạt động này áp dụng cho việc phát triển phân hệ Chấm điểm UAS7 của Dr May Day v2.0, giúp làm rõ mỗi hoạt động sản sinh ra sản phẩm gì:</p><table tabindex="0"><thead><tr><th>Hoạt động</th><th>Câu hỏi trọng tâm</th><th>Sản phẩm cụ thể cho Dr May Day v2.0</th></tr></thead><tbody><tr><td>Giao tiếp (Communication)</td><td>Bên liên quan cần gì?</td><td>Biên bản phỏng vấn bác sĩ da liễu, quy tắc thang điểm UAS7 gốc</td></tr><tr><td>Lập kế hoạch (Planning)</td><td>Cần bao lâu, bao nhiêu người?</td><td>Ước lượng Story Points, lịch trình Sprint (Chương 5)</td></tr><tr><td>Mô hình hóa (Modeling)</td><td>Hệ thống nên được cấu trúc ra sao?</td><td>DFD, Use Case, C4 Diagram (Chương 2), Class Diagram (Chương 3)</td></tr><tr><td>Xây dựng (Construction)</td><td>Làm sao hiện thực hóa đúng thiết kế?</td><td>Mã nguồn UAS7Calculator, Unit Test (Chương 7)</td></tr><tr><td>Triển khai (Deployment)</td><td>Làm sao đưa đến tay người dùng an toàn?</td><td>Pipeline CI/CD, bản ghi giám sát Production (Chương 5, 11)</td></tr></tbody></table><h4 id="_1-2-2-mo-hinh-thac-nuoc-waterfall-model" tabindex="-1">1.2.2. Mô hình Thác nước (Waterfall Model) <a class="header-anchor" href="#_1-2-2-mo-hinh-thac-nuoc-waterfall-model" aria-label="Permalink to &quot;1.2.2. Mô hình Thác nước (Waterfall Model)&quot;">​</a></h4><p>Mô hình Thác nước, phái sinh từ mô tả của Winston Royce năm 1970 (dù trớ trêu thay, bài báo gốc của Royce thực chất phê phán việc áp dụng mô hình tuần tự thuần túy này), thực hiện năm hoạt động khung theo trình tự tuyến tính nghiêm ngặt — mỗi giai đoạn phải hoàn tất và được phê duyệt trước khi giai đoạn kế tiếp bắt đầu, giống dòng nước chảy xuống không thể chảy ngược.</p><p>Yêu cầu <code> ext │ ▼ Thiết kế │ ▼ Xây dựng (Coding) │ ▼ Kiểm thử │ ▼ Triển khai &amp; Bảo trì </code></p><p>Hình 1.2 — Mô hình Thác nước tuyến tính</p><p>Ưu điểm: cấu trúc đơn giản, dễ quản lý và lập kế hoạch ngân sách/tiến độ do mỗi giai đoạn có mốc hoàn thành rõ ràng; phù hợp các dự án có yêu cầu đã hoàn toàn ổn định và ít khả năng thay đổi (như phần mềm nhúng cho thiết bị y tế cần chứng nhận quy định nghiêm ngặt trước khi bắt đầu xây dựng). Nhược điểm: rủi ro rất cao nếu phát hiện sai sót yêu cầu ở giai đoạn muộn — theo đúng quy luật đường cong chi phí sửa lỗi đã học ở Chương 2 (Hình 2.1), một sai sót phát hiện ở giai đoạn Kiểm thử có thể buộc phải quay lại từ đầu giai đoạn Yêu cầu, cực kỳ tốn kém; không phù hợp với các dự án như Dr May Day v2.0 nơi yêu cầu nghiệp vụ y tế liên tục biến động theo quy định mới.</p><h4 id="_1-2-3-mo-hinh-chu-v-v-model" tabindex="-1">1.2.3. Mô hình Chữ V (V-Model) <a class="header-anchor" href="#_1-2-3-mo-hinh-chu-v-v-model" aria-label="Permalink to &quot;1.2.3. Mô hình Chữ V (V-Model)&quot;">​</a></h4><p>Mô hình Chữ V là một biến thể mở rộng của Thác nước, làm rõ tường minh mối quan hệ giữa mỗi giai đoạn phát triển (nhánh trái, đi xuống) và giai đoạn kiểm thử tương ứng (nhánh phải, đi lên) — mỗi hoạt động Kiểm chứng (Verification — &quot;chúng ta có đang xây đúng theo thiết kế không?&quot;) ở nhánh trái được ánh xạ trực tiếp đến một hoạt động Xác nhận (Validation — &quot;sản phẩm có đáp ứng đúng nhu cầu người dùng không?&quot;) tương ứng ở nhánh phải.</p><p>Yêu cầu Nghiệp vụ ╲ ╱ Kiểm thử Nghiệm thu ╲ ╱ (Acceptance Test) Đặc tả Hệ thống ╲ ╱ Kiểm thử Hệ thống ╲ ╱ (System Test) Thiết kế Kiến trúc ╲ ╱ Kiểm thử Tích hợp ╲ ╱ (Integration Test) Thiết kế Chi tiết Module╲ ╱ Kiểm thử Đơn vị ╲ ╱ (Unit Test) ╲ ╱ ╲ ╱ Xây dựng (Coding)</p><p>Hình 1.3 — Mô hình Chữ V và Ánh xạ Kiểm chứng-Xác nhận</p><p>Giá trị cốt lõi của Mô hình Chữ V: buộc đội ngũ phải hoạch định kế hoạch kiểm thử song song ngay từ giai đoạn đặc tả yêu cầu (thay vì để việc thiết kế ca kiểm thử dồn hết đến cuối dự án) — ví dụ ngay khi đặc tả yêu cầu &quot;Hệ thống phải cảnh báo khi UAS7 tuần vượt 28 điểm&quot; hoàn tất, đội Kiểm thử Nghiệm thu đã có thể bắt đầu soạn kịch bản kiểm thử tương ứng. Mô hình này đặc biệt phù hợp với phần mềm y tế cần tuân thủ tiêu chuẩn an toàn nghiêm ngặt như IEC 62304 (đã đề cập ở Chương 2), nơi mỗi yêu cầu đều phải truy vết được đến một ca kiểm thử xác nhận cụ thể.</p><h4 id="_1-2-4-mo-hinh-tien-hoa-va-xoan-oc" tabindex="-1">1.2.4. Mô hình Tiến hóa và Xoắn ốc <a class="header-anchor" href="#_1-2-4-mo-hinh-tien-hoa-va-xoan-oc" aria-label="Permalink to &quot;1.2.4. Mô hình Tiến hóa và Xoắn ốc&quot;">​</a></h4><p>Mô hình Tiến hóa (Evolutionary Models) thừa nhận thực tế rằng yêu cầu phần mềm hiếm khi được xác định đầy đủ ngay từ đầu, do đó chủ trương xây dựng phần mềm qua nhiều phiên bản tăng dần (increments), mỗi phiên bản bổ sung chức năng và tinh chỉnh dựa trên phản hồi từ phiên bản trước — trái ngược triết lý &quot;làm đúng ngay từ đầu&quot; của Thác nước.</p><p>Mô hình Xoắn ốc (Spiral Model), do Barry Boehm đề xuất năm 1988, là hiện thực nổi tiếng nhất của tư duy tiến hóa, kết hợp thêm yếu tố quản trị rủi ro tường minh vào mỗi vòng lặp. Mỗi vòng xoắn ốc đi qua bốn góc phần tư (quadrant):</p><p>Xác định Mục tiêu, Phương án thay thế, Ràng buộc <code> ext ▲ │ Lập kế hoạch ◄──────┼──────► Phân tích Rủi ro, Giai đoạn kế │ Xây dựng Bản mẫu (Prototype) tiếp │ │ ▼ Phát triển và Kiểm thử (dựa trên kết quả phân tích rủi ro) </code></p><pre><code> Mỗi vòng xoắn ốc lặp lại 4 góc phần tư trên,
 bán kính vòng xoắn tăng dần = chi phí và mức độ hoàn thiện tăng dần
</code></pre><p>Hình 1.4 — Bốn Góc phần tư của Mô hình Xoắn ốc Boehm</p><p>Điểm khác biệt cốt lõi của Spiral Model so với các mô hình tiến hóa đơn giản khác: góc phần tư &quot;Phân tích Rủi ro&quot; bắt buộc đội ngũ phải chủ động nhận diện và giảm thiểu rủi ro lớn nhất trước khi đầu tư thêm nguồn lực vào vòng lặp tiếp theo — ví dụ ở Dr May Day v2.0, nếu rủi ro lớn nhất của một vòng lặp là &quot;liệu bác sĩ có chấp nhận giao diện chấm điểm UAS7 mới hay không&quot;, đội ngũ nên xây dựng ngay một bản mẫu (prototype) tối giản để kiểm chứng trước khi đầu tư xây dựng toàn bộ tính năng.</p><h4 id="_1-2-5-ma-tran-đanh-gia-va-lua-chon-mo-hinh-sdlc" tabindex="-1">1.2.5. Ma trận Đánh giá và Lựa chọn Mô hình SDLC <a class="header-anchor" href="#_1-2-5-ma-tran-đanh-gia-va-lua-chon-mo-hinh-sdlc" aria-label="Permalink to &quot;1.2.5. Ma trận Đánh giá và Lựa chọn Mô hình SDLC&quot;">​</a></h4><p>Không có mô hình SDLC nào là &quot;tốt nhất&quot; một cách tuyệt đối — việc lựa chọn phụ thuộc vào đặc điểm cụ thể của từng dự án. Ma trận dưới đây tổng hợp tiêu chí lựa chọn dựa trên bốn yếu tố quyết định thường gặp trong thực tiễn:</p><table tabindex="0"><thead><tr><th>Tiêu chí</th><th>Thác nước</th><th>Chữ V</th><th>Xoắn ốc/Tiến hóa</th></tr></thead><tbody><tr><td>Mức độ rõ ràng của yêu cầu ban đầu</td><td>Cần rất rõ ràng, ổn định</td><td>Cần rõ ràng, có thể truy vết</td><td>Chấp nhận yêu cầu chưa đầy đủ, sẽ rõ dần</td></tr><tr><td>Mức độ rủi ro kỹ thuật của dự án</td><td>Thấp — công nghệ đã quen thuộc</td><td>Trung bình — cần kiểm chứng nghiêm ngặt</td><td>Cao — cần vòng lặp phân tích rủi ro</td></tr><tr><td>Yêu cầu tuân thủ quy định/an toàn</td><td>Trung bình</td><td>Rất cao — phù hợp thiết bị y tế, hàng không</td><td>Trung bình — tùy quy trình bổ sung</td></tr><tr><td>Khả năng chấp nhận thay đổi giữa chừng</td><td>Rất thấp — tốn kém nếu đổi giữa chừng</td><td>Thấp — tương tự Thác nước</td><td>Cao — thiết kế để đón nhận thay đổi</td></tr></tbody></table><p>Áp dụng ma trận trên cho Dr May Day v2.0: phân hệ Chấm điểm UAS7 lõi (thuật toán tính điểm, quy tắc cảnh báo) có yêu cầu tương đối ổn định và cần truy vết kiểm thử nghiêm ngặt do liên quan trực tiếp đến chẩn đoán y tế — phù hợp tư duy Mô hình Chữ V; ngược lại, phân hệ Giao diện Người dùng và trải nghiệm bác sĩ/bệnh nhân có yêu cầu còn nhiều điều chưa chắc chắn, cần thử nghiệm và thu thập phản hồi liên tục — phù hợp tư duy Tiến hóa/Agile (trình bày ở mục 1.3). Trong thực tế, nhiều dự án lớn áp dụng đồng thời nhiều tư duy quy trình khác nhau cho từng phân hệ, thay vì ép toàn bộ dự án vào một mô hình duy nhất.</p><h3 id="_1-3-phuong-phap-luan-agile-va-lean-trong-phat-trien-ung-dung" tabindex="-1">1.3. Phương pháp luận Agile và Lean trong Phát triển Ứng dụng <a class="header-anchor" href="#_1-3-phuong-phap-luan-agile-va-lean-trong-phat-trien-ung-dung" aria-label="Permalink to &quot;1.3. Phương pháp luận Agile và Lean trong Phát triển Ứng dụng&quot;">​</a></h3><p>Các mô hình cổ điển trình bày ở mục 1.2, dù mỗi mô hình có giá trị riêng, đều gặp khó khăn chung khi đối diện với tốc độ thay đổi yêu cầu nhanh chóng của phần mềm ứng dụng hiện đại. Phương pháp luận Agile ra đời như một phản ứng trực tiếp trước hạn chế này, và cùng với triết lý Lean có nguồn gốc từ ngành sản xuất, đã trở thành tư duy chủ đạo của phần lớn các đội phát triển phần mềm ứng dụng ngày nay, bao gồm cả Dr May Day v2.0.</p><h4 id="_1-3-1-tuyen-ngon-agile-va-tu-duy-phat-trien-linh-hoat" tabindex="-1">1.3.1. Tuyên ngôn Agile và Tư duy Phát triển Linh hoạt <a class="header-anchor" href="#_1-3-1-tuyen-ngon-agile-va-tu-duy-phat-trien-linh-hoat" aria-label="Permalink to &quot;1.3.1. Tuyên ngôn Agile và Tư duy Phát triển Linh hoạt&quot;">​</a></h4><p>Tháng 2 năm 2001, mười bảy kỹ sư phần mềm gặp nhau tại khu nghỉ dưỡng Snowbird, bang Utah, Hoa Kỳ, để thảo luận về các phương pháp phát triển &quot;nhẹ nhàng&quot; (lightweight) đang nổi lên như Scrum, Extreme Programming, và Crystal. Kết quả của cuộc gặp gỡ này là Tuyên ngôn Agile (Agile Manifesto), gồm bốn giá trị cốt lõi:</p><p>Con người và sự tương tác hơn là quy trình và công cụ.</p><p>Phần mềm chạy được hơn là tài liệu đầy đủ.</p><p>Hợp tác với khách hàng hơn là đàm phán hợp đồng.</p><p>Phản hồi với thay đổi hơn là bám sát kế hoạch.</p><p>Điều quan trọng cần lưu ý: mỗi giá trị đều ở dạng &quot;X hơn là Y&quot; — Tuyên ngôn Agile không phủ nhận hoàn toàn giá trị của quy trình, tài liệu, hợp đồng hay kế hoạch (vế Y vẫn có giá trị), mà chỉ khẳng định ưu tiên tương đối cao hơn cho vế X khi buộc phải đánh đổi. Đi kèm bốn giá trị là mười hai nguyên lý chi tiết hóa, trong đó nguyên lý đầu tiên — &quot;Ưu tiên cao nhất của chúng tôi là làm hài lòng khách hàng thông qua việc bàn giao sớm và liên tục phần mềm có giá trị&quot; — chính là nền tảng triết lý cho toàn bộ tư duy phát triển tăng dần, lặp lại xuyên suốt cuốn sách này.</p><h4 id="_1-3-2-khung-lam-viec-scrum" tabindex="-1">1.3.2. Khung làm việc Scrum <a class="header-anchor" href="#_1-3-2-khung-lam-viec-scrum" aria-label="Permalink to &quot;1.3.2. Khung làm việc Scrum&quot;">​</a></h4>`,37)),(t(),a(o,null,{default:h(()=>[u(c,{id:"mermaid-421",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20PB%5B%22Product%20Backlog%20(%C6%AFu%20ti%C3%AAn%20theo%20gi%C3%A1%20tr%E1%BB%8B)%22%5D%20--%3E%20SP%5B%22Sprint%20Planning%20(%C6%AF%E1%BB%9Bc%20l%C6%B0%E1%BB%A3ng%20Story%20Points)%22%5D%0A%20%20%20%20SP%20--%3E%20SB%5B%22Sprint%20Backlog%20(Cam%20k%E1%BA%BFt%202%20tu%E1%BA%A7n)%22%5D%0A%20%20%20%20SB%20--%3E%20DS%5B%22Daily%20Scrum%20(H%E1%BB%8Dp%20%C4%91%E1%BB%A9ng%2015%20ph%C3%BAt)%22%5D%0A%20%20%20%20DS%20--%3E%20DEV%5B%22Sprint%20Execution%20(Ph%C3%A1t%20tri%E1%BB%83n%20%26%20T%E1%BB%B1%20%C4%91%E1%BB%99ng%20Test)%22%5D%0A%20%20%20%20DEV%20--%3E%20DS%0A%20%20%20%20DEV%20--%3E%20POT%5B%22Shippable%20Increment%20(S%E1%BA%A3n%20ph%E1%BA%A9m%20ch%E1%BA%A1y%20%C4%91%C6%B0%E1%BB%A3c)%22%5D%0A%20%20%20%20POT%20--%3E%20SR%5B%22Sprint%20Review%20(Demo%20v%E1%BB%9Bi%20B%C3%A1c%20s%C4%A9%2FKh%C3%A1ch%20h%C3%A0ng)%22%5D%0A%20%20%20%20SR%20--%3E%20RETRO%5B%22Sprint%20Retrospective%20(C%E1%BA%A3i%20ti%E1%BA%BFn%20quy%20tr%C3%ACnh)%22%5D%0A%20%20%20%20RETRO%20--%3E%20PB%0A%20%20%20%20style%20PB%20fill%3A%23fff3e0%2Cstroke%3A%23f57c00%0A%20%20%20%20style%20SB%20fill%3A%23e1f5fe%2Cstroke%3A%230288d1%0A%20%20%20%20style%20POT%20fill%3A%23e8f5e9%2Cstroke%3A%23388e3c%2Cstroke-width%3A2px%0A"})]),fallback:h(()=>[...n[1]||(n[1]=[g(" Loading... ",-1)])]),_:1})),n[6]||(n[6]=i('<p><em>Hình 1.2: Vòng đời khung làm việc Scrum hoàn chỉnh áp dụng trong dự án phần mềm ứng dụng.</em></p><p>Scrum, do Ken Schwaber và Jeff Sutherland hệ thống hóa, là khung làm việc Agile được áp dụng rộng rãi nhất trong công nghiệp phần mềm, tổ chức công việc thành các chu kỳ ngắn lặp lại gọi là Sprint (thường 1-4 tuần, phổ biến nhất là 2 tuần). Ba trụ cột cấu thành Scrum:</p><p>Ba Vai trò (Roles): Product Owner (chịu trách nhiệm tối đa hóa giá trị sản phẩm, quản lý Product Backlog), Scrum Master (đảm bảo nhóm tuân thủ và hưởng lợi từ khung Scrum, loại bỏ trở ngại), và Nhóm Phát triển (Developers, tự tổ chức thực hiện công việc).</p><p>Bốn Sự kiện (Events): Sprint Planning (lập kế hoạch đầu Sprint), Daily Scrum (đồng bộ hằng ngày, 15 phút), Sprint Review (trình diễn kết quả cuối Sprint), và Sprint Retrospective (nhìn lại quy trình để cải tiến).</p><p>Ba sản phẩm (Artifacts): Product Backlog (danh sách toàn bộ công việc dự kiến), Sprint Backlog (công việc đã chọn cho Sprint hiện tại), và Increment (phần tăng trưởng sản phẩm hoàn thành trong Sprint, có thể triển khai được).</p><p>Chương 5 của cuốn sách này sẽ đào sâu các thực hành Scrum nâng cao (Backlog Refinement, Story Points, Planning Poker) và các khung mở rộng Agile cho tổ chức nhiều nhóm (SAFe, LeSS) — mục này chỉ giới thiệu bộ khung tối thiểu làm nền tảng.</p><h4 id="_1-3-3-phuong-phap-kanban-va-triet-ly-lean-trong-phan-mem" tabindex="-1">1.3.3. Phương pháp Kanban và Triết lý Lean trong Phần mềm <a class="header-anchor" href="#_1-3-3-phuong-phap-kanban-va-triet-ly-lean-trong-phan-mem" aria-label="Permalink to &quot;1.3.3. Phương pháp Kanban và Triết lý Lean trong Phần mềm&quot;">​</a></h4><p>Kanban (tiếng Nhật nghĩa là &quot;thẻ tín hiệu&quot;), có nguồn gốc từ hệ thống sản xuất Toyota, được David Anderson chuyển thể sang phát triển phần mềm như một phương pháp trực quan hóa luồng công việc mà không áp đặt các Sprint có thời hạn cố định như Scrum. Bảng Kanban trực quan hóa công việc qua các cột trạng thái (Cần làm → Đang làm → Đang kiểm thử → Hoàn thành), với đặc trưng cốt lõi là Giới hạn Công việc Đang thực hiện (WIP Limit — Work In Progress Limit): mỗi cột chỉ được phép chứa tối đa một số lượng thẻ công việc nhất định, buộc đội ngũ phải hoàn thành việc đang làm trước khi nhận việc mới, thay vì bắt đầu quá nhiều việc song song mà không việc nào hoàn tất.</p><p><code> ext ┌───────────┐ ┌────────────┐ ┌─────────────┐ ┌───────────┐ │ Cần làm │ │ Đang làm │ │ Đang kiểm thử │ │ Hoàn thành │ │ (Backlog) │ │ (WIP giới hạn:3)│ │ (WIP giới hạn:2)│ │ │ ├───────────┤ ├────────────┤ ├─────────────┤ ├───────────┤ │ Nhắc lịch │ │ Chấm điểm │ │ Xuất báo cáo │ │ Đăng nhập │ │ tái khám │ │ UAS7 v2 │ │ PDF │ │ 2FA │ │ │ │ Cảnh báo AI │ │ │ │ Xác thực HIS │ │ │ │ │ │ │ │ │ └───────────┘ └────────────┘ └─────────────┘ └───────────┘ (3/3 - ĐẦY, (2/2 - ĐẦY, không nhận thêm) không nhận thêm) </code></p><p>Hình 1.5 — Bảng Kanban với Giới hạn WIP áp dụng cho Dr May Day v2.0</p><p>Triết lý Lean Software Development, do Mary và Tom Poppendieck chuyển thể từ Hệ thống Sản xuất Toyota (Toyota Production System) sang ngành phần mềm, xác định bảy loại lãng phí (Seven Wastes) cần loại bỏ trong quy trình phát triển:</p><table tabindex="0"><thead><tr><th>Loại Lãng phí (Lean)</th><th>Biểu hiện trong Phát triển Phần mềm</th></tr></thead><tbody><tr><td>Công việc dở dang (Partially Done Work)</td><td>Mã đã viết nhưng chưa kiểm thử, chưa tích hợp — chưa mang lại giá trị thực tế</td></tr><tr><td>Tính năng thừa (Extra Features)</td><td>Xây dựng tính năng &quot;phòng xa&quot; chưa ai yêu cầu (liên hệ Speculative Generality — Chương 3)</td></tr><tr><td>Học lại (Relearning)</td><td>Thiếu tài liệu khiến đội ngũ phải tìm hiểu lại logic đã từng biết</td></tr><tr><td>Bàn giao (Handoffs)</td><td>Thông tin thất thoát khi chuyển giao công việc giữa các nhóm/vai trò khác nhau</td></tr><tr><td>Chuyển đổi ngữ cảnh (Task Switching)</td><td>Một lập trình viên làm nhiều việc song song, giảm hiệu suất do liên tục đổi ngữ cảnh</td></tr><tr><td>Chờ đợi (Delays)</td><td>Chờ phê duyệt, chờ môi trường kiểm thử sẵn sàng, chờ review</td></tr><tr><td>Lỗi (Defects)</td><td>Lỗi phát hiện càng muộn, chi phí sửa càng cao (Hình 2.1 — Chương 2)</td></tr></tbody></table><p>Giới hạn WIP trong Kanban chính là công cụ trực tiếp chống lại lãng phí &quot;Công việc dở dang&quot; và &quot;Chuyển đổi ngữ cảnh&quot; — hai loại lãng phí phổ biến nhất trong các đội ngũ phát triển thiếu kỷ luật quy trình.</p><h4 id="_1-3-4-extreme-programming-va-ky-luat-ky-thuat" tabindex="-1">1.3.4. Extreme Programming và Kỷ luật Kỹ thuật <a class="header-anchor" href="#_1-3-4-extreme-programming-va-ky-luat-ky-thuat" aria-label="Permalink to &quot;1.3.4. Extreme Programming và Kỷ luật Kỹ thuật&quot;">​</a></h4><p>Bên cạnh Scrum (tập trung vào quản lý quy trình) và Kanban (tập trung vào trực quan hóa luồng công việc), Extreme Programming (XP), do Kent Beck phát triển cùng thời điểm với sự ra đời của Tuyên ngôn Agile, đóng góp một bộ thực hành kỹ thuật kỷ luật (engineering discipline) mà nhiều đội Scrum hiện đại vay mượn và tích hợp vào quy trình của mình:</p><p>Test-Driven Development (TDD): Viết ca kiểm thử trước khi viết mã hiện thực — trình bày chi tiết ở Chương 7.</p><p>Pair Programming (Lập trình cặp đôi): Hai lập trình viên cùng làm việc trên một máy trạm, một người viết mã (Driver) và một người quan sát/phản biện (Navigator), luân phiên vai trò định kỳ — giúp phát hiện lỗi sớm và lan tỏa tri thức trong đội ngũ.</p><p>Continuous Integration (Tích hợp Liên tục): Hợp nhất mã nguồn thường xuyên, nhiều lần trong ngày — trình bày chi tiết ở Chương 5.</p><p>Refactoring liên tục: Cải thiện cấu trúc mã nguồn thường xuyên mà không thay đổi hành vi — trình bày chi tiết ở Chương 3.</p><p>Sự phân công tự nhiên giữa ba phương pháp luận này trong thực tiễn: Scrum trả lời câu hỏi &quot;nhóm nên tổ chức công việc theo nhịp điệu nào&quot;, Kanban trả lời câu hỏi &quot;nhóm nên trực quan hóa và kiểm soát luồng công việc ra sao&quot;, còn XP trả lời câu hỏi &quot;nhóm nên viết mã với kỷ luật kỹ thuật nào&quot; — ba câu hỏi bổ trợ, không loại trừ lẫn nhau, và nhiều đội ngũ trưởng thành (bao gồm cả Dr May Day v2.0 ở giai đoạn sau này) áp dụng đồng thời cả ba theo tỷ lệ phù hợp với văn hóa riêng của mình.</p><h3 id="_1-4-van-hoa-devops-devsecops-va-đo-luong-hieu-nang-ky-thuat" tabindex="-1">1.4. Văn hóa DevOps, DevSecOps và Đo lường Hiệu năng Kỹ thuật <a class="header-anchor" href="#_1-4-van-hoa-devops-devsecops-va-đo-luong-hieu-nang-ky-thuat" aria-label="Permalink to &quot;1.4. Văn hóa DevOps, DevSecOps và Đo lường Hiệu năng Kỹ thuật&quot;">​</a></h3><p>Agile và Lean (mục 1.3) chủ yếu giải quyết cách đội ngũ phát triển tổ chức công việc; mục này mở rộng góc nhìn sang mối quan hệ giữa đội Phát triển (Dev) và đội Vận hành (Ops) — một điểm nghẽn kinh điển khác trong SDLC truyền thống mà DevOps ra đời để giải quyết. Ba mục con của phần này đi theo trình tự logic: mục 1.4.1 trình bày sự chuyển dịch văn hóa tổ chức, mục 1.4.2 mở rộng thêm khía cạnh bảo mật, và mục 1.4.3 cung cấp công cụ đo lường định lượng để biết liệu sự chuyển dịch đó có thực sự mang lại hiệu quả hay chỉ là khẩu hiệu suông.</p><h4 id="_1-4-1-su-chuyen-dich-van-hoa-tu-silo-sang-devops" tabindex="-1">1.4.1. Sự Chuyển dịch Văn hóa từ Silo sang DevOps <a class="header-anchor" href="#_1-4-1-su-chuyen-dich-van-hoa-tu-silo-sang-devops" aria-label="Permalink to &quot;1.4.1. Sự Chuyển dịch Văn hóa từ Silo sang DevOps&quot;">​</a></h4><p>Trong mô hình tổ chức truyền thống, đội Phát triển (Dev) và đội Vận hành (Ops) hoạt động như hai &quot;Silo&quot; (hầm chứa) tách biệt, thường có mục tiêu xung đột nhau: Dev được đánh giá theo tốc độ ra tính năng mới, trong khi Ops được đánh giá theo tính ổn định của hệ thống — dẫn đến tâm lý &quot;ném qua tường rào&quot; (throw over the wall), nơi Dev bàn giao phần mềm cho Ops triển khai mà không chịu trách nhiệm về hậu quả vận hành, và Ops có xu hướng chống lại mọi thay đổi vì rủi ro sự cố.</p><p>DevOps là sự chuyển dịch văn hóa và kỹ thuật xóa bỏ ranh giới Silo này, thường được tóm tắt qua mô hình CAMS do Damon Edwards và John Willis đề xuất:</p><p>Culture (Văn hóa): Dev và Ops chia sẻ chung trách nhiệm và mục tiêu, thay vì đổ lỗi cho nhau khi sự cố xảy ra.</p><p>Automation (Tự động hóa): Tự động hóa tối đa các bước build, test, deploy để giảm sai sót con người và tăng tốc độ (nền tảng cho CI/CD đã học ở Chương 5).</p><p>Measurement (Đo lường): Đo lường liên tục các chỉ số vận hành thực tế thay vì chỉ dựa vào cảm nhận chủ quan (mục 1.4.3 trình bày 4 chỉ số DORA cụ thể).</p><p>Sharing (Chia sẻ): Chia sẻ tri thức, công cụ và trách nhiệm giữa Dev và Ops, xóa bỏ tình trạng &quot;chỉ Ops mới biết cách vận hành hệ thống&quot;.</p><p>Mô hình tổ chức &quot;You build it, you run it&quot; (Amazon) là biểu hiện rõ nhất của văn hóa DevOps: chính đội ngũ viết mã cũng là đội ngũ trực tiếp chịu trách nhiệm vận hành mã đó trong môi trường Production, tạo động lực trực tiếp để viết mã dễ vận hành, dễ giám sát ngay từ đầu.</p><h4 id="_1-4-2-devsecops-va-nguyen-ly-bao-mat-dich-trai" tabindex="-1">1.4.2. DevSecOps và Nguyên lý Bảo mật Dịch trái <a class="header-anchor" href="#_1-4-2-devsecops-va-nguyen-ly-bao-mat-dich-trai" aria-label="Permalink to &quot;1.4.2. DevSecOps và Nguyên lý Bảo mật Dịch trái&quot;">​</a></h4><p>DevSecOps mở rộng thêm văn hóa DevOps bằng cách lồng ghép trách nhiệm bảo mật vào mọi giai đoạn phát triển, thay vì đối xử với bảo mật như một cổng kiểm duyệt tách biệt chỉ diễn ra ngay trước khi triển khai. Nguyên lý Dịch chuyển Bảo mật sang Trái (Shift-Left Security) chủ trương đẩy các hoạt động kiểm tra bảo mật (SAST, DAST, SCA) về càng sớm càng tốt trong vòng đời phát triển — nội dung này được trình bày đầy đủ với công cụ và quy trình cụ thể ở Chương 5, mục này chỉ giới thiệu khái niệm nền tảng để định hình tư duy &quot;bảo mật là trách nhiệm của tất cả mọi người&quot;, không chỉ riêng đội Security, xuyên suốt cuốn sách.</p><h4 id="_1-4-3-đinh-luong-hieu-nang-ky-thuat-bang-4-chi-so-dora" tabindex="-1">1.4.3. Định lượng Hiệu năng Kỹ thuật bằng 4 Chỉ số DORA <a class="header-anchor" href="#_1-4-3-đinh-luong-hieu-nang-ky-thuat-bang-4-chi-so-dora" aria-label="Permalink to &quot;1.4.3. Định lượng Hiệu năng Kỹ thuật bằng 4 Chỉ số DORA&quot;">​</a></h4>',33)),(t(),a(o,null,{default:h(()=>[u(c,{id:"mermaid-588",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20subgraph%20Throughput%5B%22T%E1%BB%91c%20%C4%91%E1%BB%99%20Chuy%E1%BB%83n%20giao%20(Velocity%20%2F%20Throughput)%22%5D%0A%20%20%20%20%20%20%20%20D1%5B%22T%E1%BA%A7n%20su%E1%BA%A5t%20Tri%E1%BB%83n%20khai%20(Deployment%20Frequency)%0A%E2%80%A2%20%C6%AFu%20t%C3%BA%3A%20Nhi%E1%BB%81u%20l%E1%BA%A7n%20%2F%20ng%C3%A0y%0A%E2%80%A2%20Trung%20b%C3%ACnh%3A%201%20l%E1%BA%A7n%20%2F%20tu%E1%BA%A7n%20-%20th%C3%A1ng%22%5D%0A%20%20%20%20%20%20%20%20D2%5B%22Th%E1%BB%9Di%20gian%20D%E1%BA%ABn%20Thay%20%C4%91%E1%BB%95i%20(Lead%20Time%20for%20Changes)%0A%E2%80%A2%20%C6%AFu%20t%C3%BA%3A%20%3C%201%20ng%C3%A0y%20(t%E1%BB%AB%20Commit%20%C4%91%E1%BA%BFn%20Prod)%0A%E2%80%A2%20Trung%20b%C3%ACnh%3A%201%20tu%E1%BA%A7n%20-%201%20th%C3%A1ng%22%5D%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20Stability%5B%22%C4%90%E1%BB%99%20%E1%BB%94n%20%C4%91%E1%BB%8Bnh%20H%E1%BB%87%20th%E1%BB%91ng%20(System%20Stability)%22%5D%0A%20%20%20%20%20%20%20%20D3%5B%22T%E1%BB%B7%20l%E1%BB%87%20Thay%20%C4%91%E1%BB%95i%20Th%E1%BA%A5t%20b%E1%BA%A1i%20(Change%20Failure%20Rate)%0A%E2%80%A2%20%C6%AFu%20t%C3%BA%3A%200%25%20-%2015%25%0A%E2%80%A2%20Trung%20b%C3%ACnh%3A%2016%25%20-%2030%25%22%5D%0A%20%20%20%20%20%20%20%20D4%5B%22Th%E1%BB%9Di%20gian%20Ph%E1%BB%A5c%20h%E1%BB%93i%20D%E1%BB%8Bch%20v%E1%BB%A5%20(Time%20to%20Restore%20Service%20%2F%20MTTR)%0A%E2%80%A2%20%C6%AFu%20t%C3%BA%3A%20%3C%201%20gi%E1%BB%9D%20(nh%E1%BB%9D%20Rollback%20t%E1%BB%B1%20%C4%91%E1%BB%99ng)%0A%E2%80%A2%20Trung%20b%C3%ACnh%3A%20%3C%201%20ng%C3%A0y%22%5D%0A%20%20%20%20end%0A%20%20%20%20style%20Throughput%20fill%3A%23e3f2fd%2Cstroke%3A%231976d2%2Cstroke-width%3A2px%0A%20%20%20%20style%20Stability%20fill%3A%23fbe9e7%2Cstroke%3A%23d84315%2Cstroke-width%3A2px%0A"})]),fallback:h(()=>[...n[2]||(n[2]=[g(" Loading... ",-1)])]),_:1})),n[7]||(n[7]=i('<p><em>Hình 1.3: Bốn chỉ số DORA tiêu chuẩn định lượng năng lực kỹ thuật và hiệu năng phân phối phần mềm.</em></p><p>Làm sao biết một đội ngũ DevOps đang hoạt động hiệu quả hay không, ngoài cảm nhận chủ quan? Nhóm nghiên cứu DORA (DevOps Research and Assessment), qua nhiều năm khảo sát hàng nghìn tổ chức công nghệ (công bố trong cuốn sách Accelerate của Nicole Forsgren, Jez Humble và Gene Kim), xác định bốn chỉ số định lượng có tương quan chặt chẽ với cả tốc độ phát triển lẫn độ ổn định hệ thống — bác bỏ ngộ nhận phổ biến rằng tốc độ và ổn định là hai mục tiêu đánh đổi lẫn nhau:</p><table tabindex="0"><thead><tr><th>Chỉ số DORA</th><th>Định nghĩa</th><th>Nhóm đo lường</th></tr></thead><tbody><tr><td>Deployment Frequency</td><td>Tần suất triển khai thành công lên Production</td><td>Tốc độ (Throughput)</td></tr><tr><td>Lead Time for Changes</td><td>Thời gian từ khi commit mã đến khi chạy thành công trên Production</td><td>Tốc độ (Throughput)</td></tr><tr><td>Mean Time to Restore (MTTR)</td><td>Thời gian trung bình để khôi phục dịch vụ sau sự cố</td><td>Ổn định (Stability)</td></tr><tr><td>Change Failure Rate</td><td>Tỷ lệ phần trăm các lần triển khai gây ra sự cố cần khắc phục</td><td>Ổn định (Stability)</td></tr></tbody></table><p>Nghiên cứu DORA phân loại các tổ chức thành bốn nhóm hiệu năng (Elite, High, Medium, Low) dựa trên bốn chỉ số này:</p><table tabindex="0"><thead><tr><th>Nhóm hiệu năng</th><th>Deployment Frequency</th><th>Lead Time</th><th>MTTR</th><th>Change Failure Rate</th></tr></thead><tbody><tr><td>Elite</td><td>Theo yêu cầu (nhiều lần/ngày)</td><td>Dưới 1 giờ</td><td>Dưới 1 giờ</td><td>0-15%</td></tr><tr><td>High</td><td>1 lần/tuần đến 1 lần/tháng</td><td>1 ngày đến 1 tuần</td><td>Dưới 1 ngày</td><td>0-15%</td></tr><tr><td>Medium</td><td>1 lần/tháng đến 1 lần/6 tháng</td><td>1 tuần đến 1 tháng</td><td>1 ngày đến 1 tuần</td><td>0-15%</td></tr><tr><td>Low</td><td>Ít hơn 1 lần/6 tháng</td><td>Hơn 6 tháng</td><td>Hơn 1 tuần</td><td>46-60%</td></tr></tbody></table><p>Ví dụ áp dụng tính toán cho Dr May Day v2.0 ở Sprint gần nhất: nhóm triển khai thành công 12 lần trong 2 tuần (Deployment Frequency ≈ theo yêu cầu, gần mức Elite); thời gian trung bình từ commit đến chạy Production là 3 giờ (Lead Time — mức High); trong 12 lần triển khai có 1 lần gây sự cố nhỏ (Change Failure Rate ≈ 8,3% — mức Elite); sự cố đó được khắc phục trong 40 phút (MTTR — mức Elite). Đối chiếu bốn chỉ số, đội ngũ Dr May Day v2.0 đạt gần ngưỡng Elite Performer — một cơ sở định lượng cụ thể để báo cáo tiến bộ kỹ thuật cho Ban Giám đốc bệnh viện, thay vì chỉ mô tả định tính &quot;đội ngũ làm việc hiệu quả&quot;.</p><h3 id="_1-5-xu-huong-tien-phong-ai-augmented-sdlc" tabindex="-1">1.5. Xu hướng Tiên phong: AI-Augmented SDLC <a class="header-anchor" href="#_1-5-xu-huong-tien-phong-ai-augmented-sdlc" aria-label="Permalink to &quot;1.5. Xu hướng Tiên phong: AI-Augmented SDLC&quot;">​</a></h3>',7)),(t(),a(o,null,{default:h(()=>[u(c,{id:"mermaid-756",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20A%5B%221.%20Thu%20th%E1%BA%ADp%20Y%C3%AAu%20c%E1%BA%A7u%0A(LLM%20t%C3%B3m%20t%E1%BA%AFt%20ph%E1%BB%8Fng%20v%E1%BA%A5n%2C%0Aph%C3%A1t%20hi%E1%BB%87n%20m%C3%A2u%20thu%E1%BA%ABn)%22%5D%20--%3E%20B%5B%222.%20Thi%E1%BA%BFt%20k%E1%BA%BF%20Ki%E1%BA%BFn%20tr%C3%BAc%0A(GenAI%20g%E1%BB%A3i%20%C3%BD%20m%E1%BA%ABu%20C4%2C%0A%C4%91%E1%BB%91i%20chi%E1%BA%BFu%20Best%20Practices)%22%5D%0A%20%20%20%20B%20--%3E%20C%5B%223.%20Vi%E1%BA%BFt%20m%C3%A3%20%26%20T%C3%A1i%20c%E1%BA%A5u%20tr%C3%BAc%0A(Copilot%2FClaude%20Code%0Asinh%20m%C3%A3%2C%20Unit%20Test%20t%E1%BB%B1%20%C4%91%E1%BB%99ng)%22%5D%0A%20%20%20%20C%20--%3E%20D%5B%224.%20%C4%90%E1%BA%A3m%20b%E1%BA%A3o%20Ch%E1%BA%A5t%20l%C6%B0%E1%BB%A3ng%0A(AI%20sinh%20Test%20Cases%20bi%C3%AAn%2C%0Aph%C3%A2n%20t%C3%ADch%20b%E1%BA%A3o%20m%E1%BA%ADt%20SAST)%22%5D%0A%20%20%20%20D%20--%3E%20E%5B%225.%20V%E1%BA%ADn%20h%C3%A0nh%20%26%20SRE%0A(AIOps%20ph%C3%A2n%20t%C3%ADch%20log%2C%0Ad%E1%BB%B1%20b%C3%A1o%20s%E1%BB%B1%20c%E1%BB%91%20b%E1%BA%A5t%20th%C6%B0%E1%BB%9Dng)%22%5D%0A%20%20%20%20style%20C%20fill%3A%23e8eaf6%2Cstroke%3A%233f51b5%2Cstroke-width%3A2px%0A"})]),fallback:h(()=>[...n[3]||(n[3]=[g(" Loading... ",-1)])]),_:1})),n[8]||(n[8]=i('<p><em>Hình 1.4: Bản đồ tác động của AI tạo sinh (GenAI &amp; LLMs) lên 5 giai đoạn của SDLC hiện đại.</em></p><p>Chương này khép lại bằng một xu hướng đang định hình lại toàn bộ ngành công nghiệp phần mềm trong những năm gần đây: sự tích hợp sâu rộng của Trí tuệ Nhân tạo Tạo sinh (Generative AI) và Mô hình Ngôn ngữ Lớn (Large Language Models - LLM) vào mọi giai đoạn của SDLC — chủ đề sẽ được đào sâu với công cụ và kỹ thuật cụ thể ở Chương 9 (Kỹ thuật Phần mềm Tăng cường AI).</p><h4 id="_1-5-1-tac-đong-cua-genai-va-llm-len-cac-giai-đoan-sdlc" tabindex="-1">1.5.1. Tác động của GenAI và LLM lên các Giai đoạn SDLC <a class="header-anchor" href="#_1-5-1-tac-đong-cua-genai-va-llm-len-cac-giai-đoan-sdlc" aria-label="Permalink to &quot;1.5.1. Tác động của GenAI và LLM lên các Giai đoạn SDLC&quot;">​</a></h4><p>Đối chiếu với năm hoạt động khung tổng quát ở Hình 1.1, GenAI hiện diện ngày càng sâu ở mọi giai đoạn: hỗ trợ soạn thảo và làm rõ tài liệu yêu cầu ở giai đoạn Giao tiếp; gợi ý kiến trúc và mẫu thiết kế ở giai đoạn Mô hình hóa; sinh mã nguồn, tự động hoàn thành (autocomplete) và refactor ở giai đoạn Xây dựng; sinh ca kiểm thử tự động ở giai đoạn Kiểm thử; và phân tích log, gợi ý khắc phục sự cố ở giai đoạn Triển khai/Vận hành. Không có giai đoạn nào của SDLC hoàn toàn nằm ngoài tầm ảnh hưởng của xu hướng này.</p><h4 id="_1-5-2-chuyen-dich-vai-tro-lap-trinh-vien" tabindex="-1">1.5.2. Chuyển dịch Vai trò Lập trình viên <a class="header-anchor" href="#_1-5-2-chuyen-dich-vai-tro-lap-trinh-vien" aria-label="Permalink to &quot;1.5.2. Chuyển dịch Vai trò Lập trình viên&quot;">​</a></h4><p>Khi các công cụ AI đảm nhiệm ngày càng nhiều công việc viết mã thường quy (boilerplate code, các mẫu lặp lại quen thuộc), vai trò trọng tâm của lập trình viên đang dịch chuyển từ &quot;người viết mã&quot; sang &quot;người điều phối và thẩm định&quot; (Orchestrator and Reviewer) — kỹ năng đọc hiểu, đánh giá phản biện và kiểm chứng chất lượng mã nguồn do AI sinh ra trở nên quan trọng ngang bằng, thậm chí quan trọng hơn kỹ năng tự tay viết mã từ đầu. Nghịch lý thú vị của xu hướng này: nền tảng vững chắc về Kỹ thuật Phần mềm truyền thống — chính là nội dung cốt lõi của cuốn sách này, từ Chương 2 đến Chương 6 — trở nên quan trọng hơn bao giờ hết, vì đó là năng lực giúp phân biệt mã nguồn AI sinh ra là tốt hay tồi, an toàn hay tiềm ẩn rủi ro.</p><h4 id="_1-5-3-thach-thuc-rui-ro-bao-mat-va-ao-giac-cua-mo-hinh-ai" tabindex="-1">1.5.3. Thách thức, Rủi ro Bảo mật và Ảo giác của Mô hình AI <a class="header-anchor" href="#_1-5-3-thach-thuc-rui-ro-bao-mat-va-ao-giac-cua-mo-hinh-ai" aria-label="Permalink to &quot;1.5.3. Thách thức, Rủi ro Bảo mật và Ảo giác của Mô hình AI&quot;">​</a></h4><p>Bên cạnh lợi ích về tốc độ, việc tích hợp AI vào SDLC đặt ra ba nhóm rủi ro mà Chương 9 sẽ phân tích sâu hơn:</p><p>Ảo giác (Hallucination): Mô hình AI có thể sinh ra mã nguồn trông hợp lý về mặt cú pháp nhưng chứa lỗi logic tinh vi, hoặc tệ hơn — gợi ý gọi đến các thư viện/gói phần mềm không tồn tại (Package Hallucination), một rủi ro bảo mật nghiêm trọng nếu kẻ tấn công đăng ký sẵn một gói độc hại trùng tên với gói &quot;ảo giác&quot; mà AI thường xuyên gợi ý.</p><p>Rủi ro Bảo mật tiềm ẩn: Mã nguồn do AI sinh ra có thể vô tình tái tạo lại các mẫu mã không an toàn đã học được từ dữ liệu huấn luyện công khai (như truy vấn SQL nối chuỗi trực tiếp, dễ tổn thương SQL Injection) — nhấn mạnh tầm quan trọng của việc áp dụng đầy đủ SAST/DAST/SCA (Chương 5) cho mọi đoạn mã, bất kể do người hay AI viết ra.</p><p>Rủi ro Phụ thuộc Quá mức (Over-reliance): Lập trình viên, đặc biệt người mới, có thể chấp nhận gợi ý của AI mà không đủ năng lực thẩm định, dần mai một khả năng tư duy giải quyết vấn đề độc lập — một dạng Nợ Kỹ thuật mới ở cấp độ năng lực con người, không chỉ ở cấp độ mã nguồn.</p><p>Nguyên tắc thực hành xuyên suốt cuốn sách này: công cụ AI nên được xem là một trợ lý tăng cường năng suất, không phải một sự thay thế cho tư duy Kỹ thuật Phần mềm nghiêm túc — mọi mã nguồn, dù do người hay AI viết ra, đều phải tuân thủ cùng một tiêu chuẩn về SOLID (Chương 3), kiểm thử (Chương 7), và bảo mật (Chương 5, 11) trước khi được chấp nhận vào hệ thống Dr May Day v2.0.</p><p>Bảng tổng kết dưới đây liên hệ năm mục lớn của chương này với các chương chuyên sâu tương ứng trong cuốn sách, đóng vai trò một &quot;bản đồ định hướng&quot; cho hành trình học tập tiếp theo:</p><table tabindex="0"><thead><tr><th>Mục trong Chương 1</th><th>Chủ đề Nền tảng</th><th>Chương Chuyên sâu Tương ứng</th></tr></thead><tbody><tr><td>1.1</td><td>Tư duy Kỹ thuật Phần mềm, Nợ Kỹ thuật</td><td>Chương 3 (SOLID, Tái cấu trúc)</td></tr><tr><td>1.2</td><td>Mô hình SDLC cổ điển, Kiểm chứng/Xác nhận</td><td>Chương 2 (Kỹ thuật Yêu cầu), Chương 7 (Kiểm thử)</td></tr><tr><td>1.3</td><td>Agile, Scrum, Kanban, Lean, XP</td><td>Chương 5 (Scrum Nâng cao, SAFe/LeSS)</td></tr><tr><td>1.4</td><td>DevOps, DevSecOps, Chỉ số DORA</td><td>Chương 5 (CI/CD, SAST/DAST/SCA)</td></tr><tr><td>1.5</td><td>AI-Augmented SDLC, Rủi ro AI</td><td>Chương 9 (AI4SE, Trợ lý Lập trình)</td></tr></tbody></table><h2 id="_3-case-study-thuc-te-nganh-real-world-case-study" tabindex="-1">3. CASE STUDY THỰC TẾ NGÀNH (REAL-WORLD CASE STUDY) <a class="header-anchor" href="#_3-case-study-thuc-te-nganh-real-world-case-study" aria-label="Permalink to &quot;3. CASE STUDY THỰC TẾ NGÀNH (REAL-WORLD CASE STUDY)&quot;">​</a></h2><p>Case Study: Lựa chọn Mô hình Phát triển và Thiết lập Văn hóa Kỹ thuật cho Dr May Day v2.0 — Bài học Khởi đầu Dự án</p><p>Bối cảnh Thách thức: Khi khởi động dự án Dr May Day v2.0, đội ngũ sáng lập (2 kỹ sư phần mềm và 1 bác sĩ da liễu cố vấn) đứng trước một quyết định nền tảng: áp dụng mô hình Thác nước truyền thống mà bệnh viện đối tác quen thuộc (yêu cầu tài liệu đặc tả đầy đủ trước khi phê duyệt ngân sách), hay áp dụng tư duy Agile linh hoạt hơn phù hợp với một sản phẩm còn nhiều điều chưa chắc chắn về nhu cầu người dùng thực tế. Quyết định sai lầm ban đầu — chọn thuần túy Thác nước cho toàn bộ dự án — khiến đội ngũ mất 6 tuần soạn thảo một tài liệu đặc tả yêu cầu 80 trang, nhưng khi bản demo đầu tiên được trình diễn cho bác sĩ, phản hồi nhận được là giao diện chấm điểm UAS7 hoàn toàn không phù hợp với luồng thao tác thực tế trong phòng khám — một minh chứng sống động cho thách thức Hệ thống Xã hội-Kỹ thuật đã trình bày ở mục 1.1.3. Áp lực càng lớn hơn khi ngân sách đầu tư ban đầu chỉ đủ cho 4 tháng phát triển trước khi phải trình diễn kết quả khả thi (proof of concept) cho nhà đầu tư — 6 tuần &quot;mất trắng&quot; vì tài liệu không phản ánh đúng thực tế đã tiêu tốn gần 40% quỹ thời gian quý báu đó.</p><p>Giải pháp Kỹ thuật:</p><ol><li><p>Áp dụng Ma trận Đánh giá SDLC theo từng phân hệ: Thay vì ép toàn bộ dự án vào một mô hình duy nhất, đội ngũ phân loại lại theo mục 1.2.5 — phân hệ thuật toán tính điểm UAS7 (yêu cầu ổn định, cần truy vết kiểm thử) giữ tư duy Chữ V; phân hệ giao diện người dùng (yêu cầu chưa chắc chắn) chuyển hẳn sang tư duy Tiến hóa/Agile.</p></li><li><p>Thiết lập Scrum với Sprint 2 tuần: Đội ngũ áp dụng ba trụ cột Scrum ở mục 1.3.2, tổ chức Sprint Review có sự tham gia trực tiếp của bác sĩ cố vấn mỗi 2 tuần — thay vì chờ 6 tuần mới nhận phản hồi như mô hình Thác nước ban đầu.</p></li><li><p>Dùng Bảng Kanban cho các tác vụ vận hành song song: Bên cạnh Sprint Backlog của Scrum, đội ngũ vận hành một bảng Kanban riêng (theo Hình 1.5) cho các tác vụ bảo trì và sửa lỗi phát sinh liên tục, với giới hạn WIP nghiêm ngặt để tránh phân tán nguồn lực.</p></li><li><p>Thiết lập Văn hóa DevOps ngay từ đầu: Dù đội ngũ ban đầu chỉ có 2 kỹ sư, họ áp dụng ngay mô hình &quot;You build it, you run it&quot; — chính người viết mã cũng trực tiếp theo dõi log Production, tạo thói quen viết mã dễ giám sát ngay từ những dòng đầu tiên, tránh phải tái cấu trúc tốn kém sau này khi đội ngũ mở rộng.</p></li><li><p>Bắt đầu đo lường DORA từ Sprint đầu tiên: Dù quy mô còn nhỏ, đội ngũ thiết lập theo dõi 4 chỉ số DORA ngay từ đầu (mục 1.4.3), tạo đường cơ sở (baseline) để đo lường tiến bộ khi đội ngũ và độ phức tạp hệ thống tăng lên theo thời gian — thay vì đợi đến khi &quot;đủ lớn mới đo lường&quot;, một sai lầm phổ biến khiến việc thiết lập văn hóa đo lường trở nên khó khăn hơn nhiều khi thực hiện muộn.</p></li></ol><p>Kết quả định lượng sau khi điều chỉnh chiến lược (so sánh 6 tuần đầu Thác nước thuần túy với 6 tuần đầu áp dụng chiến lược hỗn hợp):</p><table tabindex="0"><thead><tr><th>Chỉ số</th><th>6 tuần đầu (Thác nước thuần túy)</th><th>6 tuần sau khi điều chỉnh (Hỗn hợp)</th></tr></thead><tbody><tr><td>Thời gian nhận phản hồi đầu tiên từ bác sĩ</td><td>6 tuần (chỉ 1 lần duy nhất)</td><td>2 tuần/lần (3 lần phản hồi liên tục)</td></tr><tr><td>Số lần thiết kế lại giao diện do sai lệch nhu cầu</td><td>1 lần lớn (toàn bộ UI phải làm lại)</td><td>3 lần nhỏ, chi phí thấp (điều chỉnh dần theo Sprint)</td></tr><tr><td>Độ phủ tài liệu đặc tả có thể truy vết kiểm thử (phân hệ UAS7)</td><td>Không áp dụng (chưa đến giai đoạn kiểm thử)</td><td>100% — mọi yêu cầu UAS7 có ca kiểm thử tương ứng (Mô hình Chữ V)</td></tr></tbody></table><p>Bài học Rút ra: Không có mô hình SDLC nào đúng hay sai một cách tuyệt đối — sai lầm không nằm ở việc chọn Thác nước, mà ở việc áp dụng một mô hình duy nhất cho toàn bộ dự án mà không phân tích đặc thù của từng phân hệ theo Ma trận Đánh giá ở mục 1.2.5. Đồng thời, việc thiết lập văn hóa kỹ thuật tốt (DevOps, đo lường DORA) ngay từ ngày đầu — dù đội ngũ còn rất nhỏ — luôn dễ dàng và ít tốn kém hơn nhiều so với việc cố gắng thiết lập lại khi hệ thống đã phức tạp và đội ngũ đã mở rộng.</p><p>Câu chuyện khởi đầu này của Dr May Day v2.0 xuất hiện xuyên suốt toàn bộ cuốn sách như dự án nền tảng — mọi khái niệm được học ở Chương 2 (Kỹ thuật Yêu cầu) đến Chương 12 (Kiến trúc Vi Giao diện) đều được minh họa trên cùng một hệ thống liên tục phát triển này, giúp người học thấy rõ mối liên hệ giữa các chủ đề tưởng chừng tách biệt thay vì học từng khái niệm rời rạc không có bối cảnh chung.</p><h2 id="_4-bai-tap-thuc-hanh-xuyen-suot-hands-on-lab" tabindex="-1">4. BÀI TẬP THỰC HÀNH XUYÊN SUỐT (HANDS-ON LAB) <a class="header-anchor" href="#_4-bai-tap-thuc-hanh-xuyen-suot-hands-on-lab" aria-label="Permalink to &quot;4. BÀI TẬP THỰC HÀNH XUYÊN SUỐT (HANDS-ON LAB)&quot;">​</a></h2><p>Tên Bài Thực hành: Dr May Day v2.0 - Áp dụng Ma trận Lựa chọn SDLC, Thiết lập Bảng Kanban và Tính toán Chỉ số DORA Cơ sở</p><p>Mục tiêu Lab: Vận dụng Ma trận Đánh giá SDLC để phân loại các phân hệ của một dự án giả định, thiết lập bảng Kanban với giới hạn WIP, và tính toán 4 chỉ số DORA từ một tập dữ liệu triển khai mẫu.</p><h4 id="_4-1-đieu-kien-tien-đe-va-tech-stack" tabindex="-1">4.1. Điều kiện Tiền đề và Tech Stack <a class="header-anchor" href="#_4-1-đieu-kien-tien-đe-va-tech-stack" aria-label="Permalink to &quot;4.1. Điều kiện Tiền đề và Tech Stack&quot;">​</a></h4><p>Công cụ: Trello hoặc Jira (bảng Kanban), Google Sheets/Excel (tính toán DORA).</p><p>Tech Stack: Không yêu cầu lập trình ở bài Lab chương này — trọng tâm là tư duy quy trình và đo lường.</p><h4 id="_4-2-yeu-cau-cai-đat-tung-buoc" tabindex="-1">4.2. Yêu cầu Cài đặt từng bước <a class="header-anchor" href="#_4-2-yeu-cau-cai-đat-tung-buoc" aria-label="Permalink to &quot;4.2. Yêu cầu Cài đặt từng bước&quot;">​</a></h4><p>Bước 1: Áp dụng Ma trận Đánh giá SDLC</p><p>Cho bốn phân hệ giả định của một dự án y tế số mới: (a) Thuật toán chẩn đoán AI cốt lõi; (b) Giao diện đặt lịch hẹn cho bệnh nhân; (c) Module tích hợp thanh toán bảo hiểm; (d) Trang thông tin giới thiệu công khai. Áp dụng Ma trận ở mục 1.2.5, bạn đề xuất mô hình SDLC phù hợp nhất cho từng phân hệ kèm giải thích dựa trên bốn tiêu chí của bảng.</p><p>Bước 2: Thiết lập Bảng Kanban với Giới hạn WIP</p><p>Tạo bảng Kanban trên Trello/Jira với tối thiểu 4 cột (Cần làm, Đang làm, Đang kiểm thử, Hoàn thành), thiết lập giới hạn WIP cho hai cột giữa theo mẫu Hình 1.5, thêm tối thiểu 8 thẻ công việc giả định và quan sát điều gì xảy ra khi cố tình vượt giới hạn WIP.</p><p>Bước 3: Nhận diện Bảy Lãng phí Lean</p><p>Từ nhật ký làm việc một tuần giả định cho trước (mô tả các sự kiện: chờ phê duyệt 2 ngày, một lập trình viên làm 3 task song song, một lỗi phát hiện muộn ở giai đoạn UAT...), bạn phân loại từng sự kiện vào đúng một trong Bảy Lãng phí Lean ở mục 1.3.3.</p><p>Bước 4: Tính toán 4 Chỉ số DORA</p><p>Cho một tập dữ liệu lịch sử triển khai giả định trong một tháng (30 bản ghi gồm: thời điểm commit, thời điểm deploy thành công, có gây sự cố hay không, thời điểm khôi phục nếu có sự cố), bạn tính toán: Deployment Frequency (số lần/tuần), Lead Time trung bình, Change Failure Rate (%), và MTTR trung bình. Đối chiếu kết quả với ngưỡng tham khảo Elite/High/Medium/Low ở mục 1.4.3 để xác định đội ngũ giả định thuộc nhóm nào.</p><p>Bước 5: Phân tích Rủi ro AI-Augmented</p><p>Cho một đoạn mã nguồn Python do một công cụ AI sinh ra (chứa một lời gọi import đến một thư viện không có thật và một câu truy vấn SQL nối chuỗi trực tiếp), bạn xác định và ghi chú lại hai loại rủi ro tương ứng đã học ở mục 1.5.3 (Package Hallucination và lỗ hổng SQL Injection tiềm ẩn).</p><p>Bước 6: Viết Bảng Tổng kết Liên hệ Chương</p><p>Dựa theo mẫu bảng ở mục 2 cuối phần Nội dung Lý thuyết, bạn tự tổng hợp một bảng ngắn ghi lại: với mỗi mục lớn 1.1-1.5, một câu hỏi mà bạn còn thắc mắc và mong muốn được giải đáp sâu hơn ở chương chuyên sâu tương ứng — bài tập này giúp bạn chủ động định hướng việc học các chương tiếp theo thay vì tiếp nhận thụ động.</p><h4 id="_4-3-tieu-chi-đanh-gia-va-san-pham-đau-ra" tabindex="-1">4.3. Tiêu chí Đánh giá và Sản phẩm Đầu ra <a class="header-anchor" href="#_4-3-tieu-chi-đanh-gia-va-san-pham-đau-ra" aria-label="Permalink to &quot;4.3. Tiêu chí Đánh giá và Sản phẩm Đầu ra&quot;">​</a></h4><p>[ ] Bảng phân loại 4 phân hệ theo Ma trận SDLC có giải thích hợp lý dựa trên đúng bốn tiêu chí.</p><p>[ ] Bảng Kanban hoạt động với giới hạn WIP được thiết lập và minh chứng bằng ảnh chụp màn hình.</p><p>[ ] Bảng phân loại Bảy Lãng phí Lean gán đúng từng sự kiện vào đúng loại lãng phí.</p><p>[ ] Bảng tính DORA có công thức rõ ràng và kết luận đúng nhóm hiệu năng (Elite/High/Medium/Low).</p><p>[ ] Báo cáo LAB_REPORT.md xác định đúng hai loại rủi ro AI trong đoạn mã cho sẵn.</p><h2 id="_5-cau-hoi-thao-luan-va-phan-tich-thuc-chien" tabindex="-1">5. CÂU HỎI THẢO LUẬN VÀ PHÂN TÍCH THỰC CHIẾN <a class="header-anchor" href="#_5-cau-hoi-thao-luan-va-phan-tich-thuc-chien" aria-label="Permalink to &quot;5. CÂU HỎI THẢO LUẬN VÀ PHÂN TÍCH THỰC CHIẾN&quot;">​</a></h2><p>Phân biệt &quot;Viết mã&quot; và &quot;Kỹ thuật Phần mềm&quot; theo định nghĩa IEEE 610.12? Cho ví dụ cụ thể trong Dr May Day v2.0 minh họa sự khác biệt này.</p><p>Thảo luận bốn thuộc tính cố hữu (Essence) của độ khó phần mềm theo Fred Brooks, và phân tích vì sao các thuộc tính này không thể loại bỏ hoàn toàn dù công nghệ có tiến bộ đến đâu.</p><p>Giải thích khái niệm Hệ thống Xã hội-Kỹ thuật? Phân tích tình huống trong Case Study của chương minh họa hậu quả khi bỏ qua khía cạnh xã hội của hệ thống.</p><p>So sánh Mô hình Thác nước và Mô hình Chữ V? Trong bối cảnh nào Mô hình Chữ V được ưu tiên lựa chọn hơn Thác nước thuần túy đối với phần mềm y tế?</p><p>Thảo luận bốn góc phần tư của Mô hình Xoắn ốc Boehm, và phân tích vai trò của góc phần tư &quot;Phân tích Rủi ro&quot; trong việc giúp Mô hình Xoắn ốc khác biệt so với các mô hình tiến hóa đơn giản khác.</p><p>Phân tích bốn giá trị của Tuyên ngôn Agile, và giải thích vì sao mỗi giá trị được viết dưới dạng &quot;X hơn là Y&quot; thay vì phủ nhận hoàn toàn vế Y.</p><p>So sánh Scrum và Kanban? Phân tích vai trò của Giới hạn WIP trong việc chống lại các loại lãng phí Lean nào đã học ở mục 1.3.3.</p><p>Phân tích 4 Chỉ số DORA và giải thích vì sao nghiên cứu DORA bác bỏ ngộ nhận rằng tốc độ triển khai và độ ổn định hệ thống là hai mục tiêu đánh đổi lẫn nhau.</p><p>Phân tích ba nhóm rủi ro khi tích hợp AI vào SDLC đã trình bày ở mục 1.5.3? Đề xuất một biện pháp phòng ngừa cụ thể cho rủi ro Package Hallucination.</p><p>Phân tích Định luật Hyrum và giải thích mối liên hệ của nó với thuộc tính Độ phức tạp (Complexity) trong bốn thuộc tính cố hữu của Brooks, và cho một ví dụ khác ngoài Dr May Day v2.0 minh họa định luật này.</p><h2 id="_6-tai-lieu-tham-khao-va-cong-cu-references-va-tech-stack" tabindex="-1">6. TÀI LIỆU THAM KHẢO VÀ CÔNG CỤ (REFERENCES VÀ TECH STACK) <a class="header-anchor" href="#_6-tai-lieu-tham-khao-va-cong-cu-references-va-tech-stack" aria-label="Permalink to &quot;6. TÀI LIỆU THAM KHẢO VÀ CÔNG CỤ (REFERENCES VÀ TECH STACK)&quot;">​</a></h2><h4 id="_6-1-sach-giao-khoa-va-bai-bao-khoa-hoc-trong-tam" tabindex="-1">6.1. Sách Giáo khoa và Bài báo Khoa học Trọng tâm <a class="header-anchor" href="#_6-1-sach-giao-khoa-va-bai-bao-khoa-hoc-trong-tam" aria-label="Permalink to &quot;6.1. Sách Giáo khoa và Bài báo Khoa học Trọng tâm&quot;">​</a></h4><ul><li>[@pressman2020software] Pressman, R. S., &amp; Maxim, B. R. (2020). <em>Software Engineering: A Practitioner&#39;s Approach</em> (9th ed.). McGraw-Hill Education.</li><li>[@sommerville2016software] Sommerville, I. (2016). <em>Software Engineering</em> (10th ed.). Pearson Education.</li><li>[@winters2020software] Winters, T., Manshreck, T., &amp; Wright, H. (2020). <em>Software Engineering at Google: Lessons Learned from Programming Over Time</em>. O&#39;Reilly Media.</li><li>[@kim2016devopshandbook] Kim, G., Humble, J., Debois, P., &amp; Willis, J. (2016). <em>The DevOps Handbook: How to Create World-Class Agility, Reliability, and Security in Technology Organizations</em>. IT Revolution Press.</li><li>[@forsgren2018accelerate] Forsgren, N., Humble, J., &amp; Kim, G. (2018). <em>Accelerate: The Science of Lean Software and DevOps: Building and Scaling High Performing Technology Organizations</em>. IT Revolution Press.</li><li>[@brooks1987nosilver] Brooks, F. P. (1987). &quot;No silver bullet: Essence and accidents of software engineering.&quot; <em>IEEE Computer</em>, 20(4), 10–19.</li><li>[@royce1970managing] Royce, W. W. (1970). &quot;Managing the development of large software systems.&quot; <em>Proceedings of IEEE WESCON</em>, 1–9.</li><li>[@boehm1988spiral] Boehm, B. W. (1988). &quot;A spiral model of software development and enhancement.&quot; <em>IEEE Computer</em>, 21(5), 61–72.</li><li>[@beck2001manifesto] Beck, K., et al. (2001). <em>Manifesto for Agile Software Development</em>. <a href="https://agilemanifesto.org" target="_blank" rel="noreferrer">https://agilemanifesto.org</a></li><li>[@huyen2025aiengineering] Huyen, C. (2025). <em>AI Engineering: Building Applications with Foundation Models</em>. O&#39;Reilly Media.</li><li>[@bourque2014swebok] Bourque, P., &amp; Fairley, R. E. (2014). <em>Guide to the Software Engineering Body of Knowledge (SWEBOK Guide) Version 3.0</em>. IEEE Computer Society.</li></ul><h4 id="_6-2-cong-cu-khuyen-nghi-recommended-tech-stack" tabindex="-1">6.2. Công cụ Khuyến nghị (Recommended Tech Stack) <a class="header-anchor" href="#_6-2-cong-cu-khuyen-nghi-recommended-tech-stack" aria-label="Permalink to &quot;6.2. Công cụ Khuyến nghị (Recommended Tech Stack)&quot;">​</a></h4><p>Quản lý Quy trình: Jira, Trello, Azure DevOps.</p><p>Đo lường DORA: Google Cloud&#39;s DORA Quick Check, LinearB, Sleuth.</p><p>Trợ lý Lập trình AI: GitHub Copilot, Cursor, Claude Code (chi tiết ở Chương 9).</p>',66))])}const C=r(l,[["render",p]]);export{A as __pageData,C as default};
